}

function toNum(v) {
  if (v.k === 'n') return v
  if (v.k === 'b') return num(v.v ? 1 : 0)
  if (v.k === 's') return err('#VALUE!')
  return v
}
function fin(x) { return Number.isFinite(x) ? num(x) : err('#DIV/0!') }

const rank = { n: 0, s: 1, b: 2 }
function compare(a, b) {
  if (a.k !== b.k) return rank[a.k] - rank[b.k]
  if (a.k === 's') {
    const x = Array.from(a.v), y = Array.from(b.v)
    for (let i = 0; i < Math.min(x.length, y.length); i++) {
      const d = x[i].codePointAt(0) - y[i].codePointAt(0)
      if (d) return d
    }
    return x.length - y.length
  }
  return Number(a.v) - Number(b.v)
}

const CMPOPS = ['=', '<>', '<', '<=', '>', '>=']
function evaluate(n) {
  switch (n.n) {
    case 'num': return num(n.v)
    case 'bool': return { k: 'b', v: n.v }
    case 'ref': return refValue(n.w)
    case 'range': return err('#ERR!')
    case 'un': {
      const v = toNum(evaluate(n.e))
      if (v.k === 'e') return v
      return num(n.op === '-' ? -v.v : v.v)
    }
    case 'bin': {
      const l = evaluate(n.l)
      if (l.k === 'e') return l
      const r = evaluate(n.r)
      if (r.k === 'e') return r
      if (CMPOPS.includes(n.op)) {
        const d = compare(l, r)
        const res = { '=': d === 0, '<>': d !== 0, '<': d < 0, '<=': d <= 0, '>': d > 0, '>=': d >= 0 }[n.op]
        return { k: 'b', v: res }
      }
      const a = toNum(l)
      if (a.k === 'e') return a
      const b = toNum(r)
      if (b.k === 'e') return b
      switch (n.op) {
        case '+': return fin(a.v + b.v)
        case '-': return fin(a.v - b.v)
        case '*': return fin(a.v * b.v)
        case '/': return b.v === 0 ? err('#DIV/0!') : fin(a.v / b.v)
        case '^': return fin(Math.pow(a.v, b.v))
      }
      return err('#ERR!')
    }
    case 'call': return call(n)
  }
  return err('#ERR!')
}

function expandArg(a) {
  if (a.n === 'range') {
    const ks = rangeKeys(a.a, a.b)
    if (!ks) return [err('#REF!')]
    return ks.map(cellValue)
  }
  return [evaluate(a)]
}

function call(n) {
  const { name, args } = n
  if (['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'].includes(name)) {
    if (args.length < 1) return err('#ERR!')
    const vals = []
    for (const a of args) vals.push(...expandArg(a))
    for (const v of vals) if (v.k === 'e') return v
    if (name === 'COUNT') return num(vals.filter((v) => v.k === 'n').length)
    const nums = []
    for (const v of vals) {
      const x = toNum(v)
      if (x.k === 'e') return x
      nums.push(x.v)
    }
    if (name === 'SUM') return fin(nums.reduce((s, x) => s + x, 0))
    if (name === 'AVG') return fin(nums.reduce((s, x) => s + x, 0) / nums.length)
    if (name === 'MIN') return num(nums.reduce((s, x) => Math.min(s, x)))
    return num(nums.reduce((s, x) => Math.max(s, x)))
  }
  if (name === 'ABS') {
    if (args.length !== 1) return err('#ERR!')
    const vs = expandArg(args[0])
    if (vs.length !== 1) return err('#ERR!')
    const x = toNum(vs[0])
    return x.k === 'e' ? x : num(Math.abs(x.v))
  }
  if (name === 'IF') {
    if (args.length !== 3) return err('#ERR!')
    const cs = expandArg(args[0])
    if (cs.length !== 1) return err('#ERR!')
    const c = cs[0]
    if (c.k === 'e') return c
    if (c.k === 's') return err('#VALUE!')
    const truth = c.k === 'b' ? c.v : c.v !== 0
    const br = expandArg(args[truth ? 1 : 2])
    return br.length === 1 ? br[0] : err('#ERR!')
  }
  return err('#NAME?')
}

// ---- deps ----
function collect(n, set) {
  if (!n) return
  switch (n.n) {
    case 'ref': { const a = parseAddr(n.w); if (a) set.add(key(a.c, a.r)); break }
    case 'range': { const ks = rangeKeys(n.a, n.b); if (ks) for (const k of ks) set.add(k); break }
    case 'un': collect(n.e, set); break
    case 'bin': collect(n.l, set); collect(n.r, set); break
    case 'call': for (const a of n.args) collect(a, set); break
  }
}

function fmt(v) {
  if (v.k === 'e') return v.v
  if (v.k === 'b') return v.v ? 'TRUE' : 'FALSE'
  if (v.k === 's') return v.v
  return String(Number(v.v.toPrecision(10)))
}

let out = ''
for (const k of sorted) {
  const cell = cells.get(k)
  if (mode === 'values') out += `${keyName(k)}=${fmt(cellValue(k))}\n`
  else {
    const set = new Set()
    if (cell.content[0] === '=') collect(getAst(cell), set)
    out += `${keyName(k)}:` + [...set].sort((x, y) => x - y).map((x) => ' ' + keyName(x)).join('') + '\n'
  }
}
process.stdout.write(out)

